// BR Code reference: https://www.bcb.gov.br/content/estabilidadefinanceira/pix/Regulamento_Pix/II_ManualdePadroesparaIniciacaodoPix.pdf
const field=(id,value)=>id+String(value.length).padStart(2,'0')+value;
const plain=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
export function crc16(text){let crc=0xffff;for(const char of new TextEncoder().encode(text)){crc^=char<<8;for(let i=0;i<8;i++)crc=(crc&0x8000)?((crc<<1)^0x1021)&0xffff:(crc<<1)&0xffff}return crc.toString(16).toUpperCase().padStart(4,'0')}
export function pixPayload({key,name,city,cents,reference}){if(!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(key||''))throw Error('Chave PIX aleatória inválida.');if(!Number.isInteger(cents)||cents<=0||cents>999900)throw Error('Valor PIX inválido.');const merchant=plain(name).slice(0,25),town=plain(String(city).split('/')[0]).slice(0,15),txid=String(reference||'').replace(/[^a-z0-9]/gi,'').slice(0,25)||'***';if(!merchant||!town)throw Error('Dados do recebedor incompletos.');const payload=field('00','01')+field('26',field('00','br.gov.bcb.pix')+field('01',key))+field('52','0000')+field('53','986')+field('54',(cents/100).toFixed(2))+field('58','BR')+field('59',merchant)+field('60',town)+field('62',field('05',txid))+'6304';return payload+crc16(payload)}
